# Chuyên khảo đặc biệt theo Tên Chi (Genus) cho các chi cây thuốc Việt Nam nổi tiếng
GENUS_SPECIAL_NOTES: Dict[str, str] = {
    "Abelmoschus": "Chi Vông vang / Sâm bố chính (Abelmoschus): Nổi bật với rễ củ hình nhân sâm giàu chất nhầy bổ dưỡng và hoa lớn 5 cánh màu đỏ hồng hoặc vàng tâm tím.",
    "Panax": "Chi Nhân sâm (Panax): Nhóm dược liệu quý bậc nhất (như Sâm Ngọc Linh, Tam thất) chứa hàm lượng saponin dammarane và ocotillol đặc hữu.",
    "Polyscias": "Chi Đinh lăng (Polyscias): Cây thuốc bổ quen thuộc của Việt Nam, rễ chứa saponin giúp tăng tuần hoàn não và bồi bổ sức khỏe.",
    "Curcuma": "Chi Nghệ (Curcuma): Thân rễ giàu hoạt chất curcuminoid và tinh dầu thơm, dùng hành khí hoạt huyết, bảo vệ niêm mạc dạ dày và gan mật.",
    "Alpinia": "Chi Riềng (Alpinia): Thân rễ và quả giàu tinh dầu ấm nóng, chuyên dùng ôn trung tán hàn, trị đau bụng lạnh và phong thấp.",
    "Zingiber": "Chi Gừng (Zingiber): Thân rễ chứa gingerol và shogaol có tác dụng giải cảm phong hàn, làm ấm tỳ vị và chống nôn.",
    "Solanum": "Chi Cà (Solanum): Bao gồm các loài cây thuốc quý như Cà gai leo giúp giải độc gan, chống xơ gan và kháng viêm.",
    "Crinum": "Chi Náng / Trinh nữ hoàng cung (Crinum): Cây thân hành lớn có hoa trắng thơm, chứa alkaloid crinane hỗ trợ điều trị u xơ lành tính.",
    "Phyllanthus": "Chi Diệp hạ châu (Phyllanthus): Hàng quả nhỏ mọc dưới cành lá, nổi tiếng với công dụng thanh can giải độc và bảo vệ gan.",
    "Stephania": "Chi Bình vôi (Stephania): Dây leo có củ lớn trên đá vôi và lá hình khiên tròn, chứa hoạt chất rotundin giúp an thần, dễ ngủ.",
    "Dendrobium": "Chi Hoàng thảo / Thạch hộc (Dendrobium): Nhóm phong lan dược liệu quý giúp tư âm dưỡng vị, sinh tân dịch và thanh nhiệt.",
    "Artemisia": "Chi Ngải / Thanh hao (Artemisia): Giàu tinh dầu và sesquiterpene lactone (như artemisinin), dùng điều kinh, giảm đau và thanh nhiệt.",
    "Ocimum": "Chi Hương nhu / Húng quế (Ocimum): Chứa hàm lượng cao tinh dầu eugenol kháng khuẩn, giải cảm và làm ấm đường hô hấp.",
    "Mentha": "Chi Bạc hà (Mentha): Giàu menthol tự nhiên giúp sơ tán phong nhiệt, thông mũi họng và giảm đau đầu.",
    "Senna": "Chi Muồng (Senna): Hoa vàng rực rỡ, lá và hạt (Thảo quyết minh) chứa anthraquinone giúp nhuận tràng, mát gan và an thần.",
    "Ficus": "Chi Đa / Sung / Vả (Ficus): Đặc trưng bởi nhựa mủ trắng và quả sung khép kín (syconium), dùng kiện tỳ, lợi thấp và thông sữa.",
    "Piper": "Chi Hồ tiêu / Lá lốt (Piper): Lá hình tim có gân hình cung thơm nồng, dùng trừ phong thấp, giảm đau xương khớp và kháng khuẩn.",
    "Ganoderma": "Chi Nấm Linh chi (Ganoderma): Thể quả nấm hóa gỗ bóng như sơn mài, giàu beta-glucan và ganoderic acid giúp nâng cao miễn dịch.",
}


def get_family_profile(family: str, kingdom: str = "Plantae", genus: str = "") -> Dict[str, str]:
    """Lấy thông tin đặc trưng thực vật học & dược liệu theo Họ (Family), Chi (Genus) hoặc Giới (Kingdom)."""
    if family and family in FAMILY_KNOWLEDGE_DB:
        base = dict(FAMILY_KNOWLEDGE_DB[family])
    elif kingdom == "Fungi":
        base = {
            "family_vn": f"Họ Nấm {family}" if family else "Nhóm Nấm lớn (Macrofungi)",
            "growth_form": "Sinh vật thuộc Giới Nấm (Fungi), cơ thể sinh sản dạng thể quả (mũ nấm, phiến/ống nấm và cuống nấm) hoặc dạng tai nấm bám gỗ.",
            "flower_traits": "Không có hoa và diệp lục; sinh sản bằng bào tử phát tán từ mặt dưới mũ nấm (phiến nấm hoặc lỗ ống nấm).",
            "leaf_stem_traits": "Thể quả có chất thịt mềm, dai hoặc hóa gỗ (như nhóm Linh chi, Vân chi), màu sắc từ trắng, vàng nâu đến đỏ sẫm.",
            "habitat": "Mọc hoại sinh trên gỗ mục, thảm mục rừng ẩm hoặc cộng sinh với rễ cây rừng tại Việt Nam.",
            "parts_used": "Thể quả nấm (Fruiting body) hoặc sinh khối sợi nấm.",
            "active_compounds": "Polysaccharide (beta-glucan), triterpenoid, ergosterol và acid amin thiết yếu.",
            "traditional_properties": "Vị ngọt nhạt hoặc hơi đắng, tính bình; quy kinh Tâm, Can, Phế, Thận.",
            "medicinal_uses": "Nhiều loài nấm dược liệu chứa beta-glucan, polysaccharide và triterpenoid giúp tăng cường miễn dịch, bảo vệ gan và chống oxy hóa.",
            "safety_note": "CẢNH BÁO NGHIÊM TRỌNG: Tuyệt đối không tự ý hái và ăn các loài nấm mọc hoang ngoài tự nhiên nếu chưa được chuyên gia nấm học kiểm định, vì nhiều loài nấm độc có hình thái rất giống nấm ăn.",
        }
    else:
        base = {
            "family_vn": f"Họ thực vật {family}" if family else "Thực vật hệ sinh thái Việt Nam",
            "growth_form": f"Thực vật thuộc họ {family or 'Thực vật có mạch'}, ghi nhận trong hệ thực vật và nguồn gen dược liệu Việt Nam.",
            "flower_traits": f"Cấu trúc hoa và cụm hoa mang đặc trưng phân loại của chi {genus or 'thực vật có hoa'} thuộc họ {family or 'Tracheophyta'}; màu sắc cánh hoa, số lượng nhị và bầu nhụy là dấu hiệu khóa phân loại quan trọng ngoài thực địa.",
            "leaf_stem_traits": "Hình thái phiến lá, kiểu mọc lá (mọc cách, mọc đối hay mọc vòng), hệ gân lá và đặc điểm vỏ thân giúp phân biệt chính xác với các loài cùng chi.",
            "habitat": "Phân bố tự nhiên trong hệ sinh thái nhiệt đới gió mùa tại Việt Nam hoặc được trồng bảo tồn tại các vườn thực vật, vườn dược liệu.",
            "parts_used": "Lá, hoa, thân, rễ hoặc toàn cây tùy theo bài thuốc và mục đích sử dụng.",
            "active_compounds": "Các hợp chất thứ cấp thực vật đặc trưng của họ phân loại (flavonoid, polyphenol, terpenoid, glycoside).",
            "traditional_properties": "Tính vị và công năng phụ thuộc vào bộ phận thu hái và phương pháp bào chế Y học cổ truyền.",
            "medicinal_uses": "Ghi nhận trong danh mục đa dạng sinh học và cây thuốc Việt Nam (VietMediSpecies2026); có giá trị nghiên cứu thực vật học, sinh thái và dược học cổ truyền.",
            "safety_note": "Thông tin nhận diện từ ảnh chụp phục vụ tra cứu học thuật và tham khảo thực vật học; cần tham khảo ý kiến thầy thuốc/chuyên gia trước khi sử dụng làm dược liệu.",
        }

    if genus and genus in GENUS_SPECIAL_NOTES:
        base["growth_form"] = f"{base['growth_form']} {GENUS_SPECIAL_NOTES[genus]}"

    return base
